"use client";

import * as React from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { useTheme } from "next-themes";
import { motion, AnimatePresence } from "framer-motion";
import { Shield, Menu, X, Search, Sun, Moon, BookOpen, Trophy, HelpCircle, User, Settings, LogOut, ChevronDown } from "lucide-react";
import { Button } from "@/components/ui/button";
import { navigationContent } from "@/content/navigation";
import { createClient } from "@/utils/supabase/client";
import { UserProfile } from "@/types/auth";

export function Header() {
  const { theme, setTheme } = useTheme();
  const router = useRouter();
  const [scrolled, setScrolled] = React.useState(false);
  const [mobileOpen, setMobileOpen] = React.useState(false);
  const [searchActive, setSearchActive] = React.useState(false);
  const [scrollProgress, setScrollProgress] = React.useState(0);
  const [authUser, setAuthUser] = React.useState<{ id: string } | null>(null);
  const [profile, setProfile] = React.useState<UserProfile | null>(null);
  const [userMenuOpen, setUserMenuOpen] = React.useState(false);
  const userMenuRef = React.useRef<HTMLDivElement>(null);

  // Load auth state
  React.useEffect(() => {
    const supabase = createClient();
    const loadUser = async () => {
      const { data: { user } } = await supabase.auth.getUser();
      setAuthUser(user ? { id: user.id } : null);
      if (user) {
        const { data } = await supabase
          .from("profiles")
          .select("id, full_name, username, avatar_url, profile_status")
          .eq("id", user.id)
          .single();

        // Merge Google avatar if profile doesn't have one yet
        if (data && !data.avatar_url && user.user_metadata?.avatar_url) {
          data.avatar_url = user.user_metadata.avatar_url;
        }
        if (data && !data.avatar_url && user.user_metadata?.picture) {
          data.avatar_url = user.user_metadata.picture;
        }
        setProfile(data as UserProfile | null);
      }
    };
    loadUser();
    const { data: listener } = supabase.auth.onAuthStateChange((_event, session) => {
      if (session?.user) {
        setAuthUser({ id: session.user.id });
        loadUser();
      } else {
        setAuthUser(null);
        setProfile(null);
      }
    });
    return () => listener.subscription.unsubscribe();
  }, []);

  // Close user menu on outside click
  React.useEffect(() => {
    const handler = (e: MouseEvent) => {
      if (userMenuRef.current && !userMenuRef.current.contains(e.target as Node)) {
        setUserMenuOpen(false);
      }
    };
    document.addEventListener("mousedown", handler);
    return () => document.removeEventListener("mousedown", handler);
  }, []);

  const handleSignOut = async () => {
    const supabase = createClient();
    await supabase.auth.signOut();
    setAuthUser(null);
    setProfile(null);
    setUserMenuOpen(false);
    router.push("/auth/login");
  };

  React.useEffect(() => {
    const handleScroll = () => {
      setScrolled(window.scrollY > 20);
      
      const totalHeight = document.documentElement.scrollHeight - window.innerHeight;
      if (totalHeight > 0) {
        setScrollProgress((window.scrollY / totalHeight) * 100);
      }
    };
    
    const handleKeyDown = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key === "k") {
        e.preventDefault();
        setSearchActive((prev) => !prev);
      }
    };

    window.addEventListener("scroll", handleScroll);
    window.addEventListener("keydown", handleKeyDown);
    return () => {
      window.removeEventListener("scroll", handleScroll);
      window.removeEventListener("keydown", handleKeyDown);
    };
  }, []);

  const toggleMode = () => {
    setTheme(theme === "dark" ? "light" : "dark");
  };

  return (
    <>
      <header
        className={`sticky top-0 z-50 w-full transition-all duration-300 ${
          scrolled
            ? "glass-effect border-b border-border/80 py-3 shadow-sm"
            : "bg-transparent py-5"
        }`}
      >
        <div className="max-w-7xl mx-auto px-6 flex items-center justify-between relative">
          {/* Logo Branding */}
          <Link href="/" className="flex items-center gap-2.5 shrink-0">
            <div className="relative flex items-center justify-center w-9 h-9 rounded-lg bg-primary/10 border border-primary/20">
              <Shield className="w-5 h-5 text-primary animate-pulse" />
            </div>
            <span className="font-heading text-lg font-bold tracking-tight bg-gradient-to-r from-foreground via-foreground/90 to-primary bg-clip-text text-transparent">
              Ranker&apos;s League
            </span>
          </Link>

          {/* Large Screen Navigation Links */}
          <nav className="hidden md:flex items-center gap-8">
            <Link
              href="/contests"
              className="text-sm font-semibold tracking-wide uppercase text-muted-foreground hover:text-foreground transition-colors"
            >
              Contests
            </Link>
            <Link
              href="/live"
              className="text-sm font-semibold tracking-wide uppercase text-muted-foreground hover:text-foreground transition-colors"
            >
              Live
            </Link>
            <Link
              href="/leaderboard"
              className="text-sm font-semibold tracking-wide uppercase text-muted-foreground hover:text-foreground transition-colors"
            >
              Leaderboard
            </Link>
            <Link
              href="/results"
              className="text-sm font-semibold tracking-wide uppercase text-muted-foreground hover:text-foreground transition-colors"
            >
              Results
            </Link>
            <Link
              href="/rewards"
              className="text-sm font-semibold tracking-wide uppercase text-muted-foreground hover:text-foreground transition-colors"
            >
              Rewards
            </Link>

            <Link
              href="/about"
              className="text-sm font-semibold tracking-wide uppercase text-muted-foreground hover:text-foreground transition-colors"
            >
              About
            </Link>
            <Link
              href="/blog"
              className="text-sm font-semibold tracking-wide uppercase text-muted-foreground hover:text-foreground transition-colors"
            >
              Blog
            </Link>
          </nav>

          {/* Interactive Controls */}
          <div className="hidden md:flex items-center gap-4 shrink-0">
            <Button
              variant="ghost"
              size="icon"
              onClick={() => setSearchActive(true)}
              className="text-muted-foreground hover:text-foreground relative group"
              aria-label="Search Leagues"
            >
              <Search className="w-4.5 h-4.5" />
              <span className="absolute top-10 right-0 hidden group-hover:block bg-secondary border border-border text-[9px] font-bold px-1.5 py-0.5 rounded shadow whitespace-nowrap">
                Ctrl K
              </span>
            </Button>

            <Button
              variant="ghost"
              size="icon"
              onClick={toggleMode}
              className="text-muted-foreground hover:text-foreground"
              aria-label="Toggle Theme"
            >
              <Sun className="w-4.5 h-4.5 rotate-0 scale-100 transition-all dark:-rotate-90 dark:scale-0" />
              <Moon className="absolute w-4.5 h-4.5 rotate-90 scale-0 transition-all dark:rotate-0 dark:scale-100" />
            </Button>

            {authUser ? (
              // Authenticated: User dropdown menu
              <div ref={userMenuRef} className="relative">
                <button
                  onClick={() => setUserMenuOpen(!userMenuOpen)}
                  className="flex items-center gap-2 px-3 py-1.5 rounded-xl border border-border/40 bg-card/30 hover:bg-card/60 hover:border-primary/30 transition-all duration-200"
                >
                  {profile?.avatar_url ? (
                    <img src={profile.avatar_url} alt="" className="w-7 h-7 rounded-lg object-cover" />
                  ) : (
                    <div className="w-7 h-7 rounded-lg bg-primary/10 border border-primary/20 flex items-center justify-center">
                      <span className="text-xs font-black text-primary">
                        {(profile?.full_name || profile?.username || "U")[0].toUpperCase()}
                      </span>
                    </div>
                  )}
                  <div className="flex flex-col items-start">
                    <span className="text-xs font-bold text-foreground leading-tight">
                      {profile?.full_name?.split(" ")[0] || profile?.username || "Account"}
                    </span>
                    <span className="text-[10px] text-muted-foreground leading-tight">
                      {profile?.username ? `@${profile.username}` : "Set up profile"}
                    </span>
                  </div>
                  <ChevronDown className={`w-3.5 h-3.5 text-muted-foreground transition-transform duration-200 ${userMenuOpen ? "rotate-180" : ""}`} />
                </button>

                <AnimatePresence>
                  {userMenuOpen && (
                    <motion.div
                      initial={{ opacity: 0, y: -8, scale: 0.95 }}
                      animate={{ opacity: 1, y: 0, scale: 1 }}
                      exit={{ opacity: 0, y: -8, scale: 0.95 }}
                      transition={{ duration: 0.15 }}
                      className="absolute right-0 top-full mt-2 w-52 bg-card/95 backdrop-blur-xl border border-border/50 rounded-xl shadow-2xl overflow-hidden z-50"
                    >
                      <div className="px-4 py-3 border-b border-border/30">
                        <p className="text-xs font-black">{profile?.full_name || "Welcome!"}</p>
                        <p className="text-[10px] text-muted-foreground">{profile?.username ? `@${profile.username}` : "Complete your profile"}</p>
                      </div>
                      <div className="py-1">
                        {profile?.username ? (
                          <Link
                            href={`/profile/${profile.username}`}
                            onClick={() => setUserMenuOpen(false)}
                            className="flex items-center gap-2.5 px-4 py-2.5 text-xs font-medium hover:bg-muted/30 transition-colors"
                          >
                            <User className="w-3.5 h-3.5 text-muted-foreground" />
                            My Profile
                          </Link>
                        ) : (
                          <Link
                            href="/auth/complete-profile"
                            onClick={() => setUserMenuOpen(false)}
                            className="flex items-center gap-2.5 px-4 py-2.5 text-xs font-medium text-primary hover:bg-primary/5 transition-colors"
                          >
                            <User className="w-3.5 h-3.5" />
                            Complete Profile
                          </Link>
                        )}
                        <Link
                          href="/dashboard"
                          onClick={() => setUserMenuOpen(false)}
                          className="flex items-center gap-2.5 px-4 py-2.5 text-xs font-medium hover:bg-muted/30 transition-colors"
                        >
                          <Settings className="w-3.5 h-3.5 text-muted-foreground" />
                          Dashboard
                        </Link>
                        <Link
                          href="/profile/settings"
                          onClick={() => setUserMenuOpen(false)}
                          className="flex items-center gap-2.5 px-4 py-2.5 text-xs font-medium hover:bg-muted/30 transition-colors"
                        >
                          <Settings className="w-3.5 h-3.5 text-muted-foreground" />
                          Account Settings
                        </Link>
                      </div>
                      <div className="py-1 border-t border-border/30">
                        <button
                          onClick={handleSignOut}
                          className="w-full flex items-center gap-2.5 px-4 py-2.5 text-xs font-bold text-destructive hover:bg-destructive/10 transition-colors"
                        >
                          <LogOut className="w-3.5 h-3.5" />
                          Sign Out
                        </button>
                      </div>
                    </motion.div>
                  )}
                </AnimatePresence>
              </div>
            ) : (
              // Not authenticated: Sign In button
              <Link href="/auth/login">
                <Button
                  variant="outline"
                  className="px-5 border-primary/30 text-foreground hover:border-primary hover:bg-primary/5 rounded-md"
                >
                  Sign In
                </Button>
              </Link>
            )}
          </div>

          {/* Mobile Display Controls */}
          <div className="flex md:hidden items-center gap-2 shrink-0">
            <Button
              variant="ghost"
              size="icon"
              onClick={toggleMode}
              className="text-muted-foreground"
              aria-label="Toggle Theme"
            >
              <Sun className="w-4.5 h-4.5 rotate-0 scale-100 transition-all dark:-rotate-90 dark:scale-0" />
              <Moon className="absolute w-4.5 h-4.5 rotate-90 scale-0 transition-all dark:rotate-0 dark:scale-100" />
            </Button>

            <Button
              variant="ghost"
              size="icon"
              onClick={() => setMobileOpen(!mobileOpen)}
              className="text-muted-foreground"
              aria-label="Menu"
            >
              {mobileOpen ? <X className="w-5 h-5" /> : <Menu className="w-5 h-5" />}
            </Button>
          </div>
        </div>

        {/* Scroll Progress Bar */}
        <div className="absolute bottom-0 left-0 h-[2px] bg-primary transition-all duration-100" style={{ width: `${scrollProgress}%` }} />
      </header>

      {/* Mobile Menu Drawer */}
      <AnimatePresence>
        {mobileOpen && (
          <motion.div
            initial={{ opacity: 0, y: -10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -10 }}
            transition={{ duration: 0.2 }}
            className="fixed inset-x-0 top-[60px] bottom-0 z-40 md:hidden bg-background/95 backdrop-blur-md border-b border-border overflow-y-auto"
          >
            <div className="flex flex-col gap-6 p-6 text-left">
              <div className="flex flex-col gap-4">
                <Link
                  href="/contests"
                  onClick={() => setMobileOpen(false)}
                  className="text-sm font-semibold text-foreground hover:text-primary transition-colors block"
                >
                  Contests
                </Link>
                <Link
                  href="/live"
                  onClick={() => setMobileOpen(false)}
                  className="text-sm font-semibold text-foreground hover:text-primary transition-colors block"
                >
                  Live
                </Link>
                <Link
                  href="/leaderboard"
                  onClick={() => setMobileOpen(false)}
                  className="text-sm font-semibold text-foreground hover:text-primary transition-colors block"
                >
                  Leaderboard
                </Link>
                <Link
                  href="/results"
                  onClick={() => setMobileOpen(false)}
                  className="text-sm font-semibold text-foreground hover:text-primary transition-colors block"
                >
                  Results
                </Link>
                <Link
                  href="/rewards"
                  onClick={() => setMobileOpen(false)}
                  className="text-sm font-semibold text-foreground hover:text-primary transition-colors block"
                >
                  Rewards
                </Link>

                <Link
                  href="/about"
                  onClick={() => setMobileOpen(false)}
                  className="text-sm font-semibold text-foreground hover:text-primary transition-colors block"
                >
                  About
                </Link>
                <Link
                  href="/blog"
                  onClick={() => setMobileOpen(false)}
                  className="text-sm font-semibold text-foreground hover:text-primary transition-colors block"
                >
                  Blog
                </Link>
                <Link
                  href="/contact"
                  onClick={() => setMobileOpen(false)}
                  className="text-sm font-semibold text-foreground hover:text-primary transition-colors block"
                >
                  Contact
                </Link>
              </div>

              <div className="flex flex-col gap-3 pt-4 border-t border-border/60">
                <Button
                  onClick={() => {
                    setMobileOpen(false);
                    setSearchActive(true);
                  }}
                  variant="outline"
                  className="flex items-center justify-center gap-2 w-full mt-2 h-10"
                >
                  <Search className="w-4 h-4" /> Search Platform
                </Button>
                <Button className="w-full h-10">Access Platform</Button>
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>


      {/* Global Search Dialog Overlay */}
      <AnimatePresence>
        {searchActive && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 z-50 flex items-start justify-center pt-24 px-4 bg-black/65 backdrop-blur-sm"
            onClick={() => setSearchActive(false)}
          >
            <motion.div
              initial={{ scale: 0.95, y: 10 }}
              animate={{ scale: 1, y: 0 }}
              exit={{ scale: 0.95, y: 10 }}
              className="relative w-full max-w-lg p-6 bg-card border border-border/80 rounded-2xl shadow-2xl glow-subtle"
              onClick={(e) => e.stopPropagation()}
            >
              <div className="flex items-center gap-3 border-b border-border/60 pb-4">
                <Search className="w-5 h-5 text-muted-foreground shrink-0" />
                <input
                  type="text"
                  placeholder="Type to search contests, blogs, standings..."
                  className="w-full bg-transparent border-none outline-none text-sm text-foreground placeholder:text-muted-foreground"
                  autoFocus
                />
                <button
                  onClick={() => setSearchActive(false)}
                  className="p-1 rounded-md text-muted-foreground hover:text-foreground hover:bg-muted/80 transition-colors"
                >
                  <X className="w-4 h-4" />
                </button>
              </div>

              {/* Popular tags */}
              <div className="mt-5 text-left">
                <span className="text-[10px] font-bold text-muted-foreground tracking-widest uppercase block mb-3">
                  Popular Lookups
                </span>
                <div className="flex flex-wrap gap-2">
                  {navigationContent.searchPopularTags.map((tag) => (
                    <button
                      key={tag}
                      onClick={() => setSearchActive(false)}
                      className="px-2.5 py-1 bg-secondary hover:bg-primary/5 border border-border text-[10px] font-bold rounded-md text-muted-foreground hover:text-primary transition-colors"
                    >
                      {tag}
                    </button>
                  ))}
                </div>
              </div>

              {/* Recent Leagues */}
              <div className="mt-6 text-left">
                <span className="text-[10px] font-bold text-muted-foreground tracking-widest uppercase block mb-2">
                  Dynamic Channels
                </span>
                <div className="flex flex-col gap-1.5">
                  <Link
                    href="/contests/upsc-elite"
                    onClick={() => setSearchActive(false)}
                    className="flex items-center justify-between p-3 rounded-xl bg-background border border-border/40 hover:border-primary/25 transition-all text-xs font-semibold text-foreground hover:text-primary"
                  >
                    <span className="flex items-center gap-2">
                      <Trophy className="w-3.5 h-3.5 text-primary" />
                      UPSC Civil Services Elite Replica
                    </span>
                    <span className="text-[10px] text-amber-500 font-bold uppercase">Scheduled</span>
                  </Link>
                  <Link
                    href="/contests/jee-advanced"
                    onClick={() => setSearchActive(false)}
                    className="flex items-center justify-between p-3 rounded-xl bg-background border border-border/40 hover:border-primary/25 transition-all text-xs font-semibold text-foreground hover:text-primary"
                  >
                    <span className="flex items-center gap-2">
                      <BookOpen className="w-3.5 h-3.5 text-primary" />
                      IIT JEE Advanced Adaptive Cup
                    </span>
                    <span className="text-[10px] text-emerald-500 font-bold uppercase">Open</span>
                  </Link>
                </div>
              </div>

              {/* Help callout */}
              <div className="mt-5 pt-4 border-t border-border/60 flex items-center justify-between text-[10px] text-muted-foreground">
                <span className="flex items-center gap-1">
                  <HelpCircle className="w-3.5 h-3.5" />
                  Need help?
                </span>
                <span>ESC to dismiss</span>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </>
  );
}
